  'panels.slackRemoteApprovalsOff': { es: 'Aprobar desde el móvil: no (solo la lista)', en: 'Approve from the phone: off (list only)' },
  'panels.slackRemoteDisconnect': { es: 'Desconectar', en: 'Disconnect' },
  'panels.slackRemoteIntro': { es: 'Una app tuya de Slack te manda por mensaje directo lo que los habitantes necesitan que apruebes (permisos, planes, preguntas) y lo respondes ahí con sus botones, sin salir del refugio. Si quieres seguir una conversación en el móvil, desde ella la pasas a Remote Control (app de Claude).', en: 'A Slack app of your own sends you by direct message what the dwellers need you to approve (permissions, plans, questions) and you answer it there with its buttons, without leaving the shelter. To continue a conversation on your phone, hand it to Remote Control (Claude app) from there.' },
  'panels.slackRemotePrivacy': { es: 'Solo sale lo que hay que aprobar, tal cual lo ve el diálogo del juego, en texto plano, con los tokens y claves tapados y los caracteres invisibles a la vista; nunca lo que se habla. Va por los servidores de Slack (sin cifrado de extremo a extremo) y se guarda con las normas de tu espacio de trabajo: en el de una empresa, pregunta antes si se puede. Es otra app que la de los avisos de Slack, para que esa siga siendo de solo lectura.', en: 'Only what needs approving leaves, exactly as the game dialog shows it, as plain text, with tokens and keys masked and invisible characters shown; never what is said. It goes through Slack’s servers (no end-to-end encryption) and is kept under your workspace’s rules: in a company workspace, ask first whether that is allowed. It is a different app from the Slack notifications one, so that one stays read-only.' },
  'panels.slackRemoteStep1': { es: 'En api.slack.com/apps: Create New App → From a manifest, elige el espacio de trabajo y pega el manifiesto.', en: 'At api.slack.com/apps: Create New App → From a manifest, pick the workspace and paste the manifest.' },
  'panels.slackRemoteCopyManifest': { es: 'Copiar el manifiesto', en: 'Copy the manifest' },
  'panels.slackRemoteManifestCopied': { es: 'Manifiesto copiado.', en: 'Manifest copied.' },
  'panels.slackRemoteStep2': { es: 'Basic Information → App-Level Tokens → Generate, con el permiso connections:write: es el token de la app (xapp-).', en: 'Basic Information → App-Level Tokens → Generate, with the connections:write scope: that is the app token (xapp-).' },
  'panels.slackRemoteStep3': { es: 'Install App → Install to Workspace: el «Bot User OAuth Token» es el del bot (xoxb-). Pega los dos aquí.', en: 'Install App → Install to Workspace: the “Bot User OAuth Token” is the bot token (xoxb-). Paste both here.' },
  'panels.slackRemoteAppToken': { es: 'Token de la app (xapp-)', en: 'App token (xapp-)' },
