  'panels.closesWhateverIsOpenIn': { es: 'cierra lo abierto; en el refugio, el menú del juego: opciones, atajos, reiniciar, salir a la superficie y salir', en: 'closes whatever is open; in the shelter, the game menu: options, shortcuts, restart, go to the surface and quit' },
