  'panels.windowBarWithTheKeyboard': { es: 'barra de ventanas con el teclado: ←→ elegir, ↑↓ fila, Intro abrir, X cerrar, M minimizar, Esc salir', en: 'window bar with the keyboard: ←→ choose, ↑↓ row, Enter open, X close, M minimize, Esc exit' },
  'panels.jJInTheShelter': { es: '⌘J (J en el refugio)', en: '⌘J (J in the shelter)' },
  'panels.musicWithoutSpotifyItOpens': { es: 'la música: sin Spotify, lo abre; con Spotify delante, lo minimiza; con la pletina, la despliega en mano: Espacio ⏯, ←→ ±10 s, ⇧←→ temas, ↑↓ volumen, Intro abre Spotify, Esc salir', en: 'music: without Spotify, it opens it; with Spotify in front, it minimizes it; with the deck, it unfolds it: Space ⏯, ←→ ±10 s, ⇧←→ tracks, ↑↓ volume, Enter opens Spotify, Esc exit' },
  'panels.escAndCtrlCIn': { es: 'Esc y Ctrl+C en la terminal', en: 'Esc and Ctrl+C in the terminal' },
  'panels.goToTheProgramLike': { es: 'van al programa, como en iTerm: paran a Claude Code o salen de él', en: 'go to the program, like in iTerm: they stop Claude Code or exit it' },
